import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    idx = 0
    try:
        n = int(input_data[idx])
        idx += 1
        m = int(input_data[idx])
        idx += 1

        board = []
        for _ in range(n):
            row_str = input_data[idx]
            idx += 1
            board.append(list(row_str))

        word = input_data[idx]
        idx += 1
    except IndexError:
        return

    if not word:
        print(1)
        return

    rows = n
    cols = m
    word_len = len(word)

    visited = [[False] * cols for _ in range(rows)]
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    def backtrack(r, c, k):
        if k == word_len:
            return True
        if r < 0 or r >= rows or c < 0 or c >= cols:
            return False
        if visited[r][c]:
            return False
        if board[r][c] != word[k]:
            return False

        visited[r][c] = True

        found = False
        for dr, dc in directions:
            nr, nc = r + dr, c + dc
            if backtrack(nr, nc, k + 1):
                found = True
                break

        visited[r][c] = False
        return found

    found_word = False
    for i in range(rows):
        for j in range(cols):
            if board[i][j] == word[0]:
                if backtrack(i, j, 0):
                    found_word = True
                    break
        if found_word:
            break

    print(1 if found_word else 0)

if __name__ == "__main__":
    solve()
